function host(name: string, tag: string, classes: string, hidden = false) {
  return defineComponent({
    name,
    inheritAttrs: false,
    setup(_, { attrs, slots }) {
      return () =>
        h(
          tag,
          mergeProps({ class: classes, ...(hidden ? { 'aria-hidden': 'true' } : {}) }, attrs),
          slots.default?.(),
        )
    },
  })
}

