    items.map((node) => {
      if (node.type !== 'text') return { ...node, children: visit(node.children) }
      let value = ''
      for (const character of node.value) {
        const whitespace = /\s/.test(character)
        if (!whitespace || !inWhitespace) value += whitespace ? ' ' : character
